package mz.bam.seeky.android;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.media.*;import android.os.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicBoolean;
/** Visible, user-started microphone notes. Every note is PCM WAV, linked to its source. */
final class VoiceNotes {
 static final int PERMISSION=73;final ReaderActivity a;Recorder recorder;String pending="";
 VoiceNotes(ReaderActivity a){this.a=a;}
 void create(){if(recorder!=null){PlusUi.toast(a,"Termine a nota em curso.");return;}EditText title=PlusUi.input(a,"Título da nota",a.name+" · "+(a.chrome.current()+1),180);new UiDialog.Builder(a).setTitle("Nova nota de voz").setView(title).setPositiveButton("Gravar",(d,w)->{pending=title.getText().toString().trim();if(pending.isEmpty())pending="Nota de voz";if(a.checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},PERMISSION);else begin();}).setNegativeButton("Cancelar",null).show();}
 void permission(int request,int[] results){if(request==PERMISSION){if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED&&!pending.isEmpty())begin();else PlusUi.toast(a,"A gravação precisa de acesso ao microfone.");}}
 void begin(){try{if(a.isFinishing()||a.isDestroyed()||recorder!=null)return;SpeechEvents.State state=SpeechEvents.state;if(state.active&&!state.paused)ReadAloudService.control(a,ReadAloudService.PAUSE,state.token);recorder=new Recorder(pending);pending="";recorder.start();}catch(Exception e){if(recorder!=null)recorder.abort();recorder=null;PlusUi.error(a,e);}}
 void stop(){if(recorder!=null)recorder.stop(true);}
 void list(){PlusUi.run(a,()->{List<StudyStore.Row> rows;try(PlusStore db=new PlusStore(a)){rows=db.rows("voice_notes","uri=?",new String[]{a.uri.toString()},"created DESC",1000);}PlusUi.post(a,()->{UiPanel panel=new UiPanel(a,"Notas de voz",null,"note");panel.action("add","Gravar nota de voz",null,false,this::create);for(StudyStore.Row row:rows)panel.action("audio",row.s("title"),a.tools==null?null:a.tools.location((int)row.n("segment")),false,()->menu(row));panel.show();});});}
 void menu(StudyStore.Row row){UiPanel panel=new UiPanel(a,row.s("title"),null,"note");panel.action("play","Ouvir nota",null,false,()->a.startActivity(new Intent(a,MediaActivity.class).setDataAndType(PlusFileProvider.voice(a,row.id()),"audio/wav").putExtra("name",row.s("title")+".wav")));if(a.tools!=null)panel.action("book","Abrir passagem de origem",null,false,()->a.tools.navigate((int)row.n("segment"),(int)row.n("position"),true));panel.action("edit","Alterar título",null,false,()->{EditText title=PlusUi.input(a,"Título",row.s("title"),180);new UiDialog.Builder(a).setTitle("Nota de voz").setView(title).setPositiveButton("Guardar",(d,w)->{String value=title.getText().toString().trim();if(!value.isEmpty())PlusUi.run(a,()->{try(PlusStore db=new PlusStore(a)){db.getWritableDatabase().update("voice_notes",StudyStore.values("title",value),"id=?",new String[]{""+row.id()});}PlusUi.post(a,this::list);});}).setNegativeButton("Cancelar",null).show();});panel.danger("Eliminar nota",()->new UiDialog.Builder(a).setTitle("Eliminar esta nota de voz?").setPositiveButton("Eliminar",(d,w)->PlusUi.run(a,()->{File file=new File(row.s("path")).getCanonicalFile(),root=new File(a.getFilesDir(),"voice-notes").getCanonicalFile();if(!DiskWalker.inside(root,file))throw new IOException("Nota inválida.");try(PlusStore db=new PlusStore(a)){db.getWritableDatabase().beginTransaction();File removed=new File(root,"discard-"+UUID.randomUUID()+".tmp");boolean moved=false;try{if(file.exists()){if(!file.renameTo(removed))throw new IOException("Não foi possível remover o áudio.");moved=true;}db.getWritableDatabase().delete("voice_notes","id=?",new String[]{""+row.id()});db.getWritableDatabase().setTransactionSuccessful();}catch(Exception e){if(moved)removed.renameTo(file);throw e;}finally{db.getWritableDatabase().endTransaction();}removed.delete();}PlusUi.post(a,this::list);})).setNegativeButton("Cancelar",null).show());panel.show();}
 final class Recorder {
  final String title;final int part,position;final String uri;final long material;final AtomicBoolean stopping=new AtomicBoolean();final ExecutorService work=Executors.newSingleThreadExecutor();final Handler clock=new Handler(Looper.getMainLooper());AmbientHold ambient;AudioRecord input;UiDialog dialog;TextView status;boolean keep=true;long began;File file;
  Recorder(String title){this.title=title;part=a.chrome.current();position=a.bookText==null?0:Math.max(0,a.bookText.getSelectionStart());uri=a.uri.toString();material=a.getIntent().getLongExtra("study_material",0);}
  void start()throws Exception{int min=AudioRecord.getMinBufferSize(16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);if(min<=0)throw new IOException("O microfone não está disponível neste aparelho.");input=new AudioRecord(MediaRecorder.AudioSource.MIC,16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,Math.max(8192,min*2));if(input.getState()!=AudioRecord.STATE_INITIALIZED){input.release();throw new IOException("Não foi possível abrir o microfone.");}if(!ReadingAudioFocus.get(a).acquire(this,()->stop(true))){input.release();throw new IOException("Som ocupado por outra aplicação.");}ambient=new AmbientHold(a);File folder=new File(a.getFilesDir(),"voice-notes");folder.mkdirs();file=new File(folder,UUID.randomUUID()+".wav");status=a.text("A gravar · 00:00",15);dialog=new UiDialog.Builder(a).setTitle(title).setView(status).setPositiveButton("Parar e guardar",(d,w)->stop(true)).setNeutralButton("Descartar",(d,w)->stop(false)).create();dialog.setOnCancelListener(d->stop(true));dialog.show();input.startRecording();began=SystemClock.elapsedRealtime();clock.post(tick);work.execute(this::record);}
  final Runnable tick=new Runnable(){public void run(){if(stopping.get())return;long seconds=(SystemClock.elapsedRealtime()-began)/1000;status.setText(AppLanguage.text(a,"A gravar")+" · "+ReaderActivity.clock((int)seconds*1000)+" / 10:00");if(seconds>=600)stop(true);else clock.postDelayed(this,1000);}};
  void stop(boolean save){if(!stopping.compareAndSet(false,true))return;keep=save;clock.removeCallbacksAndMessages(null);if(input!=null)try{input.stop();}catch(IllegalStateException ignored){}if(dialog!=null&&dialog.isShowing())dialog.dismiss();}
  void abort(){stopping.set(true);clock.removeCallbacksAndMessages(null);if(input!=null){try{input.stop();}catch(Exception ignored){}input.release();input=null;}if(dialog!=null&&dialog.isShowing())dialog.dismiss();ReadingAudioFocus.get(a).release(this);if(ambient!=null)ambient.release();if(file!=null)file.delete();work.shutdown();}
  void record(){boolean saved=false;try(CheckpointWave wave=new CheckpointWave(file,0,1,1,16000,16)){byte[] buffer=new byte[8192];while(!stopping.get()){if(file.getParentFile().getUsableSpace()<16777216)throw new IOException("Sem espaço para continuar a nota.");int n=input.read(buffer,0,buffer.length);if(n<0){if(stopping.get())break;throw new IOException("A gravação foi interrompida pelo aparelho.");}n-=n%2;if(n>0){wave.out.seek(44+wave.bytes);wave.out.write(buffer,0,n);wave.bytes+=n;}}if(keep&&wave.bytes>0){wave.finish(new WavInfo(title,a.name,"Haidoy Carlos Mautempo",1));if(a.workspaceEpoch!=WorkspaceEpoch.value)throw new IOException("A biblioteca foi recuperada durante a nota. O áudio não foi associado a outro livro.");try(PlusStore db=new PlusStore(a.getApplicationContext())){db.save("voice_notes",StudyStore.values("uri",uri,"material",material,"segment",part,"position",position,"title",title,"path",file.getPath(),"created",System.currentTimeMillis()));}saved=true;}}catch(Exception e){PlusUi.post(a,()->PlusUi.error(a,e));}finally{stopping.set(true);clock.removeCallbacksAndMessages(null);if(input!=null){try{input.stop();}catch(Exception ignored){}input.release();input=null;}if(!saved&&file!=null)file.delete();final boolean success=saved;PlusUi.MAIN.post(()->{ReadingAudioFocus.get(a).release(this);if(ambient!=null)ambient.release();if(dialog!=null&&dialog.isShowing())dialog.dismiss();if(recorder==this)recorder=null;if(!a.dead&&success)PlusUi.toast(a,"Nota de voz guardada em WAV.");});work.shutdown();}}
 }
}
